class Solution { public:
 int numberOfWays(int n,int x,int y){const long long M=1000000007;vector<long long> dp(n+1);dp[0]=1;for(int i=1;i<=n;i++){for(int j=i;j>=1;j--)dp[j]=(dp[j]*j+dp[j-1])%M;dp[0]=0;}long long ans=0,ways=1;for(int j=1;j<=min(n,x);j++){ways=ways*(x-j+1)%M*y%M;ans=(ans+dp[j]*ways)%M;}return ans;}
};
